import re
import base64
import pickle
import numpy as np

def extraer_features_caso(caso):
    if not isinstance(caso, dict):
        caso = {}
    senales = caso.get("senales") or {}
    oraciones = senales.get("oraciones") or []
    fragmentos = senales.get("fragmentos") or []

    resp_texto = str(caso.get("respuesta") or "")
    fuentes = caso.get("fuentes") or []
    fuentes_texto = " ".join(str(f) for f in fuentes if f)

    resp_lower = resp_texto.lower()
    fuentes_lower = fuentes_texto.lower()

    # 1. Solapamiento léxico (palabras >= 4 letras y dígitos)
    r_words = set(re.findall(r"\b[a-záéíóúñ]{4,}\b", resp_lower))
    f_words = set(re.findall(r"\b[a-záéíóúñ]{4,}\b", fuentes_lower))
    overlap = len(r_words.intersection(f_words)) / max(len(r_words), 1)
    palabras_nuevas_ratio = len(r_words - f_words) / max(len(r_words), 1)

    # 2. Heurística Pista 10: Conectores causales, alcance y verbos fuertes
    causales = ["gracias a", "debido a", "a causa de", "como consecuencia", "motivado por", "provocó", "permitió que", "por culpa de"]
    alcance = ["todos", "todas", "siempre", "nunca", "ningún", "ninguna", "únicamente", "exclusivamente", "totalidad", "cualquier"]

    alerta_causal = sum(1.0 for c in causales if c in resp_lower and c not in fuentes_lower)
    alerta_alcance = sum(1.0 for a in alcance if re.search(rf"\b{a}\b", resp_lower) and not re.search(rf"\b{a}\b", fuentes_lower))

    # 3. Verificación numérica (cifras en respuesta frente a fuentes + sumas/restas/porcentajes)
    nums_r = [float(n.replace(".", "").replace(",", ".")) for n in re.findall(r"\b\d+(?:[\.,]\d+)?\b", resp_texto)]
    nums_f = [float(n.replace(".", "").replace(",", ".")) for n in re.findall(r"\b\d+(?:[\.,]\d+)?\b", fuentes_texto)]
    set_f = set(nums_f)
    lim_f = nums_f[:35]
    for i in range(len(lim_f)):
        set_f.add(round(lim_f[i] * 2.0, 4))
        set_f.add(round(lim_f[i] / 2.0, 4))
        set_f.add(round(lim_f[i] / 1000.0, 4))
        set_f.add(round(lim_f[i] * 1000.0, 4))
        for j in range(i + 1, len(lim_f)):
            set_f.add(round(lim_f[i] + lim_f[j], 4))
            set_f.add(round(abs(lim_f[i] - lim_f[j]), 4))

    num_huerfanos = 0.0
    for nr in nums_r:
        if nr not in set_f and not any(abs(nr - nf) <= max(1e-3, abs(nr) * 0.005) for nf in set_f):
            num_huerfanos += 1.0

    if not oraciones:
        return [0.0] * 25 + [float(overlap), float(palabras_nuevas_ratio), float(alerta_causal), float(alerta_alcance), float(num_huerfanos)]

    max_contra_fuente = []
    contra_todas_vals = []
    resp_todas_vals = []
    max_resp_fuente = []
    max_sim_fuente = []

    riesgo_llm_vals = []
    conf_raw_vals = []
    llm_no_resp_count = 0.0
    llm_contra_count = 0.0
    llm_resp_baja_conf = 0.0
    desacuerdo_juez_nli = []
    resp_fuente_citada = []

    for o in oraciones:
        if not isinstance(o, dict):
            continue

        contras = [float(c) for c in (o.get("contradiccion_por_fuente") or [0.0]) if c is not None]
        resps = [float(r) for r in (o.get("respaldo_por_fuente") or [0.0]) if r is not None]
        sims = [float(s) for s in (o.get("similitud_por_fuente") or [0.0]) if s is not None]

        c_max = max(contras) if contras else 0.0
        r_max = max(resps) if resps else 0.0
        s_max = max(sims) if sims else 0.0

        max_contra_fuente.append(c_max)
        max_resp_fuente.append(r_max)
        max_sim_fuente.append(s_max)

        r_todas = o.get("respaldo_todas")
        r_todas = float(r_todas) if r_todas is not None else r_max
        resp_todas_vals.append(r_todas)

        c_todas = o.get("contradiccion_todas")
        c_todas = float(c_todas) if c_todas is not None else c_max
        contra_todas_vals.append(c_todas)

        llm = o.get("llm") or {}
        # Buscamos cualquier clave de texto en llm que indique el veredicto
        veredicto = ""
        for k, v in llm.items():
            if isinstance(v, str) and any(w in v.lower() for w in ["respald", "contrad", "fiel", "alucin"]):
                veredicto = v.lower()
                break
        if not veredicto:
            veredicto = str(llm.get("veredicto") or llm.get("estado") or llm.get("decision") or "").lower()

        conf = llm.get("confianza")
        conf = float(conf) if conf is not None else 0.5
        conf_raw_vals.append(conf)

        if "contra" in veredicto:
            riesgo_llm = 0.5 + 0.5 * conf
            llm_contra_count += 1.0
        elif "no" in veredicto:
            riesgo_llm = 0.5 + 0.5 * conf
            llm_no_resp_count += 1.0
        elif "respald" in veredicto:
            riesgo_llm = 0.5 * (1.0 - conf)
            if conf < 0.85:
                llm_resp_baja_conf += 1.0
        else:
            riesgo_llm = conf

        riesgo_llm_vals.append(riesgo_llm)

        mejor_respaldo_nli = max(r_todas, r_max)
        if "respald" in veredicto and "no" not in veredicto:
            desacuerdo_juez_nli.append(max(0.0, conf - mejor_respaldo_nli))
        else:
            desacuerdo_juez_nli.append(0.0)

    # Fragmentos
    resp_frag_todas = []
    contra_frag_todas = []
    max_resp_frag_fuente = []
    max_contra_frag_fuente = []
    mejor_resp_por_frag = []

    for f in fragmentos:
        if not isinstance(f, dict):
            continue
        rf_t = f.get("respaldo_todas")
        rf_t_val = float(rf_t) if rf_t is not None else None
        if rf_t_val is not None:
            resp_frag_todas.append(rf_t_val)

        cf_t = f.get("contradiccion_todas")
        if cf_t is not None:
            contra_frag_todas.append(float(cf_t))

        rf_list = [float(x) for x in (f.get("respaldo_por_fuente") or []) if x is not None]
        rf_max_val = max(rf_list) if rf_list else None
        if rf_max_val is not None:
            max_resp_frag_fuente.append(rf_max_val)

        if rf_t_val is not None and rf_max_val is not None:
            mejor_resp_por_frag.append(max(rf_t_val, rf_max_val))
        elif rf_t_val is not None:
            mejor_resp_por_frag.append(rf_t_val)
        elif rf_max_val is not None:
            mejor_resp_por_frag.append(rf_max_val)

        cf_list = [float(x) for x in (f.get("contradiccion_por_fuente") or []) if x is not None]
        if cf_list:
            max_contra_frag_fuente.append(max(cf_list))

    peor_contra_fuente = max(max_contra_fuente) if max_contra_fuente else 0.0
    media_contra_fuente = float(np.mean(max_contra_fuente)) if max_contra_fuente else 0.0
    peor_contra_todas = max(contra_todas_vals) if contra_todas_vals else 0.0
    media_contra_todas = float(np.mean(contra_todas_vals)) if contra_todas_vals else 0.0

    peor_resp_todas = min(resp_todas_vals) if resp_todas_vals else 1.0
    media_resp_todas = float(np.mean(resp_todas_vals)) if resp_todas_vals else 1.0
    peor_max_resp_fuente = min(max_resp_fuente) if max_resp_fuente else 1.0
    mejor_respaldo_combinado = min(max(rt, rf) for rt, rf in zip(resp_todas_vals, max_resp_fuente)) if resp_todas_vals else 1.0

    peor_sim_max = min(max_sim_fuente) if max_sim_fuente else 0.0
    media_sim_max = float(np.mean(max_sim_fuente)) if max_sim_fuente else 0.0

    peor_riesgo_llm = max(riesgo_llm_vals) if riesgo_llm_vals else 0.0
    media_riesgo_llm = float(np.mean(riesgo_llm_vals)) if riesgo_llm_vals else 0.0
    min_conf_raw = min(conf_raw_vals) if conf_raw_vals else 1.0
    max_conf_raw = max(conf_raw_vals) if conf_raw_vals else 0.0
    max_desacuerdo = max(desacuerdo_juez_nli) if desacuerdo_juez_nli else 0.0

    peor_resp_frag = min(resp_frag_todas) if resp_frag_todas else peor_resp_todas
    peor_resp_frag_f = min(max_resp_frag_fuente) if max_resp_frag_fuente else peor_max_resp_fuente
    peor_mejor_resp_frag = min(mejor_resp_por_frag) if mejor_resp_por_frag else mejor_respaldo_combinado
    frags_sin_respaldo = sum(1.0 for x in mejor_resp_por_frag if x < 0.35)

    peor_contra_frag = max(contra_frag_todas) if contra_frag_todas else peor_contra_todas
    peor_contra_frag_f = max(max_contra_frag_fuente) if max_contra_frag_fuente else peor_contra_fuente

    brecha_oracion_frag = max(0.0, peor_resp_todas - peor_resp_frag)
    interaccion_riesgo = peor_riesgo_llm * (1.0 - mejor_respaldo_combinado)
    neto_contra_resp = max(peor_contra_todas, peor_contra_fuente) - mejor_respaldo_combinado

    return [
        float(peor_contra_fuente),
        float(media_contra_fuente),
        float(peor_contra_todas),
        float(media_contra_todas),
        float(peor_resp_todas),
        float(media_resp_todas),
        float(peor_max_resp_fuente),
        float(mejor_respaldo_combinado),
        float(peor_sim_max),
        float(media_sim_max),
        float(peor_riesgo_llm),
        float(media_riesgo_llm),
        float(min_conf_raw),
        float(max_conf_raw),
        float(llm_no_resp_count),
        float(llm_contra_count),
        float(llm_resp_baja_conf),
        float(max_desacuerdo),
        float(peor_resp_frag),
        float(peor_resp_frag_f),
        float(peor_mejor_resp_frag),
        float(frags_sin_respaldo),
        float(peor_contra_frag),
        float(peor_contra_frag_f),
        float(brecha_oracion_frag),
        float(interaccion_riesgo),
        float(neto_contra_resp),
        float(overlap),
        float(palabras_nuevas_ratio),
        float(alerta_causal),
        float(alerta_alcance),
        float(num_huerfanos)
    ]




MODELOS_B64 = ""

class Guardian:
    def __init__(self):
        self.umbral_nativo = 0.17599249
        self.m_lr, self.m_gb, self.m_et = pickle.loads(base64.b64decode(MODELOS_B64.encode("ascii")))

    def score(self, caso: dict) -> float:
        X = np.array([extraer_features_caso(caso)], dtype=float)
        p_lr = float(self.m_lr.predict_proba(X)[0, 1])
        p_gb = float(self.m_gb.predict_proba(X)[0, 1])
        p_et = float(self.m_et.predict_proba(X)[0, 1])
        prob = 0.35 * p_lr + 0.40 * p_gb + 0.25 * p_et

        u = self.umbral_nativo
        if prob < u:
            score_final = 0.5 * (prob / u) if u > 0 else 0.0
        else:
            score_final = 0.5 + 0.5 * ((prob - u) / (1.0 - u)) if u < 1.0 else 1.0

        return float(min(1.0, max(0.0, score_final)))

Bot = Guardian
